package com.alpharip.staffmod.BuildTimelapse.ui;import com.alpharip.staffmod.BuildTimelapse.timeline.*;public final class TimelinePanelModel {private final Timeline timeline;private long playhead;public TimelinePanelModel(Timeline t){if(t==null)throw new IllegalArgumentException();timeline=t;}public Timeline getTimeline(){return timeline;}public long getPlayhead(){return playhead;}public void seek(long v){playhead=Math.max(0,Math.min(timeline.duration(),v));}}
